campaign.scenes/hanged-clerk/scene.json:
{
  "id": "hanged-clerk",
  "title": "The Hanged Clerk",
  "summary": "A palace clerk hanged behind the granary, two foul-mouthed kids who know more than they say, and a dry watch sergeant with until noon.",
  "kind": "scene",
  "time": "morning",
  "onEnd": [
    {
      "op": "follow",
      "who": "kell"
    }
  ],
  "place": "granary-yard",
  "start": "yard",
  "cast": [
    {
      "id": "kell",
      "name": "Sergeant Agnes Kell",
      "card": "cast/kell.md",
      "statblock": "guard",
      "weapon": "club"
    },
    {
      "id": "cob",
      "name": "Cob",
      "card": "cast/cob.md",
      "called": "the boy in the too-big boots",
      "statblock": "commoner",
      "weapon": "unarmed-strike"
    },
    {
      "id": "moll",
      "name": "Moll",
      "card": "cast/moll.md",
      "called": "the girl in the shawl",
      "statblock": "commoner",
      "weapon": "unarmed-strike"
    },
    {
      "id": "tull",
      "name": "Corporal Abner Tull",
      "card": "cast/tull.md",
      "called": "the corporal",
      "enters": "dead-cart",
      "group": "Corporal Tull and two constables with the dead-cart",
      "statblock": "guard",
      "weapon": "club"
    }
  ],
  "facts": {
    "killed-not-suicide": "Prout didn't hang himself: what has been found shows he was killed and then hoisted up to look like a suicide.",
    "page-read": "Sewn into the lining of Prout's left boot was a page razored from the Royal Granary Roll: a dozen grain wagons for the King's Road this past month marked 'lost to goblins', each countersigned 'J. Sallow, for the Royal Purveyor', with Prout's pencilled note beside each of what the same wagon weighed at the river warehouses two days later, and at the foot: 'Not goblins. Who pays the hedge-folk?'",
    "cob-kindness": "Cob has had a kindness from the player with nothing asked back (something to eat, or a dinner stood him freely): it counts with him.",
    "cob-taken": "Cob was taken in for Prout's murder.",
    "moll-taken": "Moll was taken in for Prout's murder."
  },
  "beats": {
    "yard": {
      "title": "Stones at a hanged man",
      "text": "beats/yard.md",
      "routes": [
        {
          "id": "not-suicide",
          "on": "outcome",
          "when": "The player has found, been shown or worked out a specific sign that Prout didn't hang himself: for example the level cord mark or the blow to the head (up close), that he could only have dropped from a loft door that's barred on the inside, the scuffs or the docker's knot in the loft, the scraped heels of his boots, Moll's story falling apart, or Cob's account of the night.",
          "to": "doubt",
          "establishes": [
            "killed-not-suicide"
          ]
        },
        {
          "id": "page-found",
          "on": "outcome",
          "when": "The folded page sewn into the lining of Prout's left boot has been found and read, or read out.",
          "to": "motive",
          "establishes": [
            "page-read"
          ]
        },
        {
          "id": "examine-body",
          "on": "attempt",
          "when": "The player examines Prout's neck, head or hands up close (he's been got down, or they've climbed or been lifted up to him), where reading what they see takes some skill.",
          "check": {
            "skill": "medicine",
            "dc": 12,
            "reason": "to tell how Prout really died",
            "success": "They see what the noose didn't make: a thin, level cord mark low round the neck beneath the rope's slanting burn, a swelling under the hair at the back of the skull, and clean palms with no rope burn. He was struck and strangled, then hung up.",
            "failure": "They see rope burn, bruising and a dead clerk's face, and can't read more. Kell, at their shoulder, says 'Hm.' She has seen something; a second look, or asking her, will find it.",
            "onSuccess": "doubt"
          }
        },
        {
          "id": "win-cob",
          "on": "attempt",
          "when": "The player pushes past Cob's hostility to get him to trust them or tell what he knows, with an appeal or an argument, where it could go either way. (Not just asking him a question. Food or coin offered as the price of it gets boasts and bargaining, not this. A promise that truly answers what he's afraid of, his name kept out of it and the men from the loft kept off him, needs no dice: that's not this either.)",
          "check": {
            "skill": "persuasion",
            "dc": 13,
            "reason": "to get Cob to trust you with what he heard",
            "success": "Cob's swagger cracks. He checks Moll can't hear, then tells it in a frightened rush: he sleeps in the loft, and last night he woke to a lantern and voices, a thump and a choking noise, then the hoist creaking with no sacks on it. He hid till morning.",
            "failure": "Cob jeers, calls them a bum-faced palace pigeon and darts behind the water butt and through a gap into the granary. He's hiding, not gone: Moll knows where, and he can still be coaxed out.",
            "onSuccess": "doubt"
          }
        },
        {
          "id": "promise-cob",
          "on": "outcome",
          "when": "The player makes Cob a promise that truly answers what he's afraid of, and means it (his name kept out of it, with nothing to the watch and nothing in anybody's book; the men from the loft kept off him; no Mending House; the boots his to keep), or asks him what he knows under a promise like that made before. No dice, whatever they ask with it: he believes it, near enough. He checks Moll can't hear, then tells it in a frightened rush: he sleeps in the loft, and last night he woke to a lantern and voices, Mister Prout arguing with two men; then a thump, a choking noise and the hoist creaking with no sacks on it. He hid in his sacks till morning. Asked for a look in his boot as well, he holds the left one out himself.",
          "to": "doubt",
          "establishes": [
            "killed-not-suicide"
          ],
          "essential": "not-suicide"
        },
        {
          "id": "catch-moll",
          "on": "attempt",
          "when": "The player presses on the holes in Moll's 'I saw him jump' story, or tries to read whether she's lying, where it could go either way. (Not just asking her to tell it.)",
          "check": {
            "skill": "insight",
            "dc": 13,
            "reason": "to see through Moll's story about the jump",
            "success": "Moll's story wobbles and she knows it. Cornered, she admits through her teeth that a gentleman paid her a silver crown at first light to say she'd seen the clerk jump.",
            "failure": "Moll tells it again, louder and with new details, and Cob loyally swears to every word. The holes are still there (the barred loft door, the drizzle, debts nobody knows of) for anyone who comes at it another way.",
            "onSuccess": "doubt"
          }
        },
        {
          "id": "scare-kids",
          "on": "attempt",
          "when": "The player tries to frighten the kids into talking: threats, looming, the watch, the Mending House or Cob's father.",
          "check": {
            "skill": "intimidation",
            "dc": 12,
            "reason": "to scare the children into talking",
            "success": "Cob's bravado collapses. White-faced, he blurts that he was in the loft last night and heard men do it, and starts to cry; Moll screams blue murder at the player from the wall. Kell's mouth goes thin.",
            "failure": "Cob bolts behind the water butt and through a gap into the granary, and Moll lets fly in three languages. Kell says nothing, loudly. The kids will be harder to reach now, but they haven't gone.",
            "onSuccess": "doubt"
          }
        },
        {
          "id": "bribe-cob",
          "on": "outcome",
          "when": "The player offers Cob something as the price of a look in his boot, or at what's crackling in it (a coin held up, food, a trade: 'this is yours if I can see what's in there', 'a shilling for a look'), however politely it's asked and whatever they say about the boots staying his, and nothing that answers what he's afraid of. No dice: Cob haggles, boasts, ups the price and takes anything going, but the boot stays on. Bought attention isn't trust, and grown-ups who pay to look at his boots want them off him (the watch, his da, the pawnshop): what's really wrong comes out instead, his way. They're Cob's, and nobody's having them. (Food with nothing asked back is a kindness, not this.)",
          "to": "yard",
          "towards": "page"
        },
        {
          "id": "kind-to-cob",
          "on": "outcome",
          "when": "The player does Cob a kindness with nothing asked back: something to eat, or a dinner stood him freely, with no look at his boots (or anything else) as the price. He takes it with bad grace and a boast, and it counts with him: after it, a polite ask for a look in his boot, the boots staying his, gets a yes.",
          "to": "yard",
          "establishes": [
            "cob-kindness"
          ],
          "towards": "page"
        },
        {
          "id": "coax-cob",
          "on": "attempt",
          "when": "Before Cob has any reason to trust them (no kindness with nothing asked back done him yet, no promise that answers what he's afraid of, no yes from him already) and with nothing offered for it, the player asks Cob to let them look in his left boot, or see or feel what's crackling in it, with the boots staying his (it's what's in them they're after, not the boots), or tries to win him round to it (Mister Prout, the men from the loft, his own skin), where it could go either way. Not with anything offered for the look (a coin, food, a trade): that's a bribe, and gets haggling. Not after a kindness, with a promise that answers his fear, or once he's said they can look: then the ask needs no dice.",
          "check": {
            "skill": "persuasion",
            "dc": 12,
            "reason": "to get Cob to let you look in his boot",
            "success": "Cob scowls at them for a long moment, then sits on the edge of the water butt, unlaces the string and holds the left boot out at arm's length: 'Look, then. And Cob's having it straight back.' In the lining is something folded and stiff, held in with small neat stitches, and out comes a page, folded small and gone soft at the corners. Cob can't read it; anyone who can sees a dozen grain wagons for the King's Road marked 'lost to goblins', each countersigned 'J. Sallow, for the Royal Purveyor', with Prout's pencilled weights beside them.",
            "failure": "Cob won't, and it costs: he clamps a hand over the boot and backs off towards the water butt and his gap, and Moll drops off the wall between them, one more grown-up after Cob's boots. The boot isn't lost: a kindness with nothing asked back, a real promise, or someone saying aloud whose boots they are can still open it.",
            "onSuccess": "motive",
            "establishes": {
              "success": [
                "page-read"
              ]
            }
          },
          "essential": "page"
        },
        {
          "id": "trust-cob",
          "on": "outcome",
          "when": "The player asks Cob for a look in his left boot (or a peek at what's crackling in it), the boots staying his, once he has real reason to trust them: they did him a kindness with nothing asked back earlier (something to eat, a dinner stood him freely), or they make him a promise, now or before, that truly answers what he's afraid of (his name kept out of it, with nothing to the watch and nothing in anybody's book; the men from the loft kept off him; no Mending House; the boots his to keep), or he has already told them they can look. No dice, however it's put: he unlaces the left boot, holds it out at arm's length and lets them pick the lining open: Prout's page is out.",
          "to": "motive",
          "establishes": [
            "page-read"
          ],
          "essential": "page"
        },
        {
