          "id": "wrap-up",
          "on": "attempt",
          "when": "The player is done here without naming anyone for it: wrapping up, leaving the yard, or asking Kell to write Prout up as murdered by persons unknown or to take what they've found to the King as it stands.",
          "to": "open-case"
        },
        {
          "id": "cart-comes",
          "on": "cue",
          "when": "The scene has been at this point a good while (at least six exchanges) and the player isn't closing in on who or why, or is idling or waiting: noon comes, and so does the dead-cart.",
          "to": "dead-cart"
        }
      ]
    },
    "motive": {
      "title": "What Prout found",
      "text": "beats/motive.md",
      "routes": [
        {
          "id": "leave-with-page",
          "on": "attempt",
          "when": "The player is done here and leaves the yard (or sends Kell off) with the page in hand, without laying the case out in words: Kell has read it and will write it up herself.",
          "to": "case-made"
        },
        {
          "id": "cart-comes",
          "on": "cue",
          "when": "The player has had the page a while (at least three exchanges at this point) without making the case to Kell, or is dawdling: noon comes, and so does the dead-cart.",
          "to": "dead-cart"
        }
      ]
    },
    "dead-cart": {
      "title": "The dead-cart",
      "text": "beats/dead-cart.md",
      "routes": [
        {
          "id": "held-as-murder",
          "on": "outcome",
          "when": "Kell, given real evidence, has agreed to sign Prout in as a murder rather than a suicide, and Tull has accepted it, with nobody named for it.",
          "to": "open-case"
        },
        {
          "id": "persuade-tull",
          "on": "attempt",
          "when": "The player tries to talk Tull into waiting, or into taking Prout in as anything but a suicide, before Kell has a case she'll sign for.",
          "check": {
            "skill": "persuasion",
            "dc": 12,
            "reason": "to convince Tull to wait before taking Prout away",
            "success": "Tull sighs, folds the order away and sits on the edge of the cart: he'll wait for the sergeant's word, and take Prout in however she signs for him.",
            "failure": "Tull is very sorry, but the Captain was very clear, and he nods his constables up the ladder. One more good reason might still stop him.",
            "onSuccess": "dead-cart",
            "onFailure": "closed-suicide"
          }
        },
        {
          "id": "accuse-kid",
          "on": "attempt",
          "when": "The player accuses Cob or Moll of killing Prout (says plainly that they did it, not just asks) or tells Kell or Tull to arrest one of them for it.",
          "to": "accused"
        },
        {
          "id": "carted-off",
          "on": "cue",
          "when": "Tull's patience has run out, or the player has told him to go ahead: he has waited at least two exchanges since he arrived (or since he last agreed to wait) without being given a reason he can take back to the Captain, and the constables load Prout onto the cart as a suicide.",
          "to": "closed-suicide"
        }
      ]
    },
    "accused": {
      "title": "On what evidence?",
      "text": "beats/accused.md",
      "routes": [
        {
          "id": "insist-cob",
          "on": "attempt",
          "when": "Having heard Kell's objection, the player insists that Cob be taken in for the murder anyway, or seizes him for it themselves.",
          "to": "wrong-man",
          "establishes": [
            "cob-taken"
          ]
        },
        {
          "id": "insist-moll",
          "on": "attempt",
          "when": "Having heard Kell's objection, the player insists that Moll be taken in for the murder anyway, or seizes her for it themselves.",
          "to": "wrong-man",
          "establishes": [
            "moll-taken"
          ]
        },
        {
          "id": "drop-it",
          "on": "outcome",
          "when": "The player has let the accusation drop for now (taken it back, or turned to the evidence, the body or someone else), and Corporal Tull's dead-cart hasn't come yet.",
          "to": "doubt"
        },
        {
          "id": "drop-it-cart",
          "on": "outcome",
          "when": "The player has let the accusation drop for now, and Corporal Tull and his dead-cart are already in the yard.",
          "to": "dead-cart"
        }
      ]
    }
  },
  "anytime": [
    {
      "id": "make-case",
      "on": "outcome",
      "when": "The case is on the record: the player has made it to Kell (out loud, or by handing her the page that names him) that Prout was killed and hung up to look like a suicide by or for the man calling himself Master Sallow of the Royal Purveyor's office (the kids' 'Silvertop', or just 'the Purveyor's man'), backed by something actually found here, and Kell has accepted it and is writing it down as murder.",
      "to": "case-made"
    }
  ],
  "exits": {
    "case-made": {
      "kind": "progress",
      "title": "The case is made",
      "next": "caerwyn-afternoon",
      "text": "exits/case-made.md",
      "effects": [
        {
          "op": "quest",
          "quest": "hanged-clerk",
          "do": "complete",
          "text": "Proved Wendell Prout was murdered, and named Sallow of the Royal Purveyor's office as behind it."
        },
        {
          "op": "quest",
          "quest": "purveyors-man",
          "do": "start",
          "title": "The Purveyor's Man",
          "text": "A man calling himself Master Sallow, of the Royal Purveyor's office, had the palace clerk Wendell Prout killed and hung up as a suicide. The case needs taking to the King, not the Watch Captain."
        },
        {
          "op": "attitude",
          "who": "kell",
          "to": "friendly",
          "text": "The King's investigator made Prout's case properly."
        },
        {
          "op": "remember",
          "who": "kell",
          "text": "The King's investigator proved Prout was murdered and named Sallow of the Purveyor's office."
        },
        {
          "op": "give",
          "what": "ledger-page",
          "to": "$player",
          "if": {
            "established": "page-read"
          }
        },
        {
          "op": "flag",
          "name": "prout_death",
          "value": "murder, Sallow named"
        },
        {
          "op": "journal",
          "text": "Wendell Prout didn't hang himself. The trail leads to Master Sallow of the Royal Purveyor's office."
        }
      ]
    },
    "open-case": {
      "kind": "progress",
      "title": "Murder by persons unknown",
      "next": "caerwyn-afternoon",
      "text": "exits/open-case.md",
      "effects": [
        {
          "op": "quest",
          "quest": "hanged-clerk",
          "do": "advance",
          "stage": "murder_unnamed",
          "text": "Prout's death is on the books as murder by persons unknown."
        },
        {
          "op": "remember",
          "who": "kell",
          "text": "Prout was murdered; nobody has been named for it yet, and the case is open."
        },
        {
          "op": "give",
          "what": "ledger-page",
          "to": "$player",
          "if": {
            "established": "page-read"
          }
        },
        {
          "op": "flag",
          "name": "prout_death",
          "value": "murder, unnamed"
        },
        {
          "op": "journal",
          "text": "Prout was murdered. The watch has it down as persons unknown."
        }
      ]
    },
    "wrong-man": {
      "kind": "other",
      "title": "The wrong name in the book",
      "next": "caerwyn-afternoon",
      "text": "exits/wrong-man.md",
      "effects": [
        {
          "op": "remove",
          "what": "moll",
          "text": "the watch-house cells",
          "if": {
            "established": "moll-taken"
          }
        },
        {
          "op": "attitude",
          "who": "moll",
          "to": "hostile",
          "text": "Taken in for a murder they didn't do, on the player's word.",
          "if": {
            "established": "moll-taken"
          }
        },
        {
          "op": "attitude",
          "who": "cob",
          "to": "hostile",
          "text": "The player had their friend taken in for murder.",
          "if": {
            "established": "moll-taken"
          }
        },
        {
          "op": "remove",
          "what": "cob",
          "text": "gone to ground somewhere in the granary quarter",
          "if": {
            "established": "moll-taken"
          }
        },
        {
          "op": "remove",
          "what": "cob",
          "text": "the watch-house cells",
          "unless": {
            "established": "moll-taken"
          }
        },
        {
          "op": "attitude",
          "who": "cob",
          "to": "hostile",
          "text": "Taken in for a murder they didn't do, on the player's word.",
          "unless": {
            "established": "moll-taken"
          }
        },
        {
          "op": "attitude",
          "who": "moll",
          "to": "hostile",
          "text": "The player had their friend taken in for murder.",
          "unless": {
            "established": "moll-taken"
          }
        },
        {
          "op": "remove",
          "what": "moll",
          "text": "gone to ground somewhere in the granary quarter",
          "unless": {
            "established": "moll-taken"
          }
        },
        {
          "op": "attitude",
          "who": "kell",
          "to": "unfriendly",
          "text": "Made to arrest a child for murder on no evidence."
        },
        {
          "op": "remember",
          "who": "kell",
          "text": "She arrested a child for Prout's murder at the investigator's insistence, and wrote down her objection."
        },
        {
          "op": "quest",
          "quest": "hanged-clerk",
          "do": "fail",
          "text": "A child was taken in for Prout's murder; whoever really killed him is in the clear."
        },
        {
          "op": "flag",
          "name": "prout_death",
          "value": "murder, blamed on a granary child"
        },
        {
          "op": "journal",
          "text": "We had one of the granary kids taken in for the clerk's murder. The sergeant thinks we're wrong."
        }
      ]
    },
    "closed-suicide": {
      "kind": "other",
      "title": "Filed as a suicide",
      "next": "caerwyn-afternoon",
      "text": "exits/closed-suicide.md",
      "effects": [
        {
          "op": "quest",
          "quest": "hanged-clerk",
          "do": "fail",
          "text": "Prout was filed as a suicide."
        },
        {
          "op": "attitude",
          "who": "kell",
          "to": "wary",
          "text": "The King's investigator let Prout go down as a suicide."
        },
        {
          "op": "flag",
          "name": "prout_death",
          "value": "suicide"
        },
        {
          "op": "journal",
          "text": "The clerk behind the granary was filed as a suicide."
        }
      ]
    },
    "walked-away": {
      "kind": "leave",
      "title": "Walked away",
      "next": "caerwyn-afternoon",
      "text": "exits/walked-away.md",
      "effects": [
        {
          "op": "quest",
          "quest": "hanged-clerk",
          "do": "fail",
          "text": "Walked away before the case was made; Prout was filed as a suicide."
        },
        {
          "op": "attitude",
          "who": "kell",
          "to": "wary",
          "text": "The King's investigator walked away from Prout's case."
        },
        {
          "op": "remember",
          "who": "kell",
          "text": "The King's investigator walked off and left Prout to the dead-cart."
        },
        {
          "op": "flag",
          "name": "prout_death",
          "value": "suicide"
        }
      ]
    }
  },
  "essentials": {
    "not-suicide": {
      "what": "Prout didn't hang himself: he was struck and strangled, then hoisted up for show.",
