campaign.scenes/kings-morning/scene.json:
{
  "id": "kings-morning",
  "title": "The King's Morning",
  "summary": "The morning of the Assembly: the investigator reports to King Aldren half an hour before the procession, and the night's promises come due.",
  "kind": "scene",
  "time": "next-morning",
  "rest": "long",
  "milestone": true,
  "place": "dressing-room",
  "start": "report",
  "cast": [
    {
      "id": "king",
      "name": "King Aldren",
      "card": "cast/king.md",
      "statblock": "noble",
      "weapon": "unarmed-strike"
    },
    {
      "id": "holt",
      "name": "Marshal Garran Holt",
      "card": "cast/holt.md",
      "called": "the Marshal",
      "statblock": "knight",
      "weapon": "longsword"
    },
    {
      "id": "kell",
      "name": "Sergeant Agnes Kell",
      "card": "cast/kell.md",
      "statblock": "guard",
      "weapon": "club"
    },
    {
      "id": "sallow",
      "name": "Master Josiah Sallow",
      "card": "cast/sallow.md",
      "called": "the gentleman with the silver-topped cane",
      "enters": "face-to-face",
      "statblock": "bandit-captain",
      "weapon": "rapier"
    }
  ],
  "facts": {
    "sallow-slipped": "In front of the King, Master Sallow has given himself away: he corrected the record on the 'lost' grain, the Heron or the count before he could stop himself, or was caught out in a lie in the King's own hearing."
  },
  "beats": {
    "report": {
      "title": "The report",
      "text": "beats/report.md",
      "routes": [
        {
          "id": "told",
          "on": "outcome",
          "when": "The player has told the King what they found (who killed Prout, and why) and shown or named what proof they have, in their own way.",
          "to": "reckoning"
        },
        {
          "id": "send-for-sallow",
          "on": "attempt",
          "when": "The player asks for Master Sallow (in the gallery outside with the Purveyor's party, if he's free this morning) to be made to explain himself in front of the King ('make him explain', 'ask him where the grain went', 'call him in'), or calls him in by name, even in the same breath as accusing him or pressing the King: hearing him out comes first. No dice: it's a small thing, and the King grants it at once ('Garran, ask Master Sallow to step in').",
          "to": "face-to-face"
        },
        {
          "id": "sallow-comes-in",
          "on": "outcome",
          "when": "Master Sallow has come into the room from the gallery and is here in front of the King, whoever had him in: the King sending for him of his own accord, the Marshal, or Sallow himself, hearing his name.",
          "to": "face-to-face",
          "given": true
